package io.github.diodeme.ji.host;

import io.github.diodeme.ji.agent.AgentEvent;
import io.github.diodeme.ji.agent.AgentRun;
import io.github.diodeme.ji.agent.AgentRuntime;
import io.github.diodeme.ji.agent.AgentSession;
import io.github.diodeme.ji.agent.SessionOptions;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.session.SessionSnapshot;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Flow;

/** Shared application service used by ACP and HCP/Web; adapters never own Session state. */
public final class SessionApplicationService implements AutoCloseable {
    private final AgentRuntime runtime;
    private final Map<String, AgentSession> sessions = new ConcurrentHashMap<>();

    public SessionApplicationService(AgentRuntime runtime) {
        this.runtime = runtime;
    }

    public io.github.diodeme.ji.session.SessionStore sessionStore() {
        return runtime.sessionStore();
    }

    public AgentSession create(ModelRef model, String workingDirectory) {
        AgentSession session = runtime.newSession(new SessionOptions(model, workingDirectory));
        sessions.put(session.id(), session);
        return session;
    }

    public AgentSession load(String sessionId) {
        return sessions.computeIfAbsent(sessionId, runtime::loadSession);
    }

    public AgentRun prompt(String sessionId, String text) {
        return load(sessionId).prompt(text);
    }

    public AgentRun prompt(String sessionId, String runId, String text) {
        return load(sessionId).prompt(runId, text);
    }

    public boolean hasActiveRun(String sessionId) {
        return load(sessionId).hasActiveRun();
    }

    public SessionSnapshot snapshot(String sessionId) {
        return load(sessionId).snapshot();
    }

    public List<Message> transcript(String sessionId) {
        return snapshot(sessionId).transcript();
    }

    public Flow.Publisher<AgentEvent> events(String sessionId) {
        return load(sessionId).events();
    }

    public boolean cancel(String sessionId) {
        return load(sessionId).abort();
    }

    @Override
    public void close() {
        runtime.close();
    }
}

